
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_ms2h_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_ms2h", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.260982148102388e+00, -4.176555963979801e+00, -4.058279072898928e+00, -3.894488399438579e+00, -3.671415030339963e+00, -3.374766313603927e+00, -2.993490908122180e+00, -2.526549448528324e+00, -1.991082790681344e+00, -1.410441858953075e+00, -9.041825895987379e-01, -6.239470609024496e-01, -5.505796527602963e-01, -4.702683396954530e-01, -3.314580335352426e-01, -1.996694682826338e-01, -1.035761113891008e-01, -3.768241592352749e-02, -8.203854313931960e-03, -9.226973334484824e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


